#include "dsky_decimal_consumer_vectors.h"
uint16_t dsky_decimal_consumer_checkpoint(uint16_t n,apollo_overlay_state *s,apollo_overlay_state *before){p66_bias_io io,old;enum dsky_nv_mission mission;agc_word channel;enum dsky_decimal_consumer_route route=(enum dsky_decimal_consumer_route)3;uint16_t f,p,end,failures=0;if(n>=DSKY_DECIMAL_CONSUMER_FROZEN_COUNT)return 1;dsky_decimal_consumer_input(s,&io,dsky_decimal_consumer_numbers[n],&mission,&channel);p=dsky_decimal_consumer_before_offsets[n];end=dsky_decimal_consumer_before_offsets[n+1u];while(p<end){uint16_t at=dsky_decimal_consumer_before_patch[p][0],value=dsky_decimal_consumer_before_patch[p++][1];if(at<2048u)s->words[at]=value;else if(at==2048u)io.superbank=value;else if(at==2049u)io.interrupt_enabled=value;else return 1;}*before=*s;old=io;if(dsky_decimal_consumer(s,&io,mission,(enum dsky_decimal_consumer_stage)dsky_decimal_consumer_stages[n],channel,&route)!=P66_BIAS_OK)++failures;p=dsky_decimal_consumer_after_offsets[n];end=dsky_decimal_consumer_after_offsets[n+1u];for(f=0;f<2051u;++f){uint16_t expected=f<2048u?before->words[f]:f==2048u?old.superbank:f==2049u?old.interrupt_enabled:3;uint16_t actual=f<2048u?s->words[f]:f==2048u?io.superbank:f==2049u?io.interrupt_enabled:(uint16_t)route;if(p<end&&dsky_decimal_consumer_after_patch[p][0]==f)expected=dsky_decimal_consumer_after_patch[p++][1];if(actual!=expected)++failures;}if(p!=end)++failures;return failures;}
